  <div class="hero-controls" id="heroDots"></div>
</section>

<section class="quick-entry">
  <h2 class="section-label">快速入口 · 按国家</h2>
  <div class="chip-row">
    <a class="chip" href="#">泰剧</a>
    <a class="chip" href="#">韩剧</a>
    <a class="chip" href="#">内地</a>
    <a class="chip" href="#">日剧</a>
    <a class="chip" href="#">全部国家</a>
