<footer>
  <div class="foot-brand">
    <div class="display">绝对BL</div>
    <p>这是我一个人的观剧存档，记录看过的每一部剧、每一对CP、每一次心动瞬间。数据仅保存在本地，不涉及其他用户。</p>
  </div>
  <div class="foot-links">
    <div>
      <h4>浏览</h4>
      <ul><li><a href="#">剧集列表</a></li><li><a href="#">配对标签</a></li><li><a href="#">排行榜</a></li></ul>
    </div>
    <div>
      <h4>我的</h4>
      <ul><li><a href="#">收藏夹</a></li><li><a href="#">剧评区</a></li><li><a href="#">评分记录</a></li></ul>
    </div>
    <div>
      <h4>联系</h4>
      <ul><li><a href="#">留言板（可选）</a></li></ul>
    </div>
  </div>
  <div class="copyright">© 2026 绝对BL · 个人观剧记录站 · 第一版设计文档演示数据</div>
</footer>

<script>
(function(){
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- Hero carousel ---- */
  const slides = document.querySelectorAll('.slide');
  const dotsWrap = document.getElementById('heroDots');
  let current = 0, timer;

  slides.forEach((_, i) => {
    const dot = document.createElement('button');
    dot.className = 'hero-dot' + (i === 0 ? ' active' : '');
    dot.setAttribute('aria-label', '第 ' + (i + 1) + ' 张');
    dot.addEventListener('click', () => goTo(i));
    dotsWrap.appendChild(dot);
  });
  const dots = document.querySelectorAll('.hero-dot');

  function goTo(index){
    slides[current].classList.remove('active');
    dots[current].classList.remove('active');
    current = (index + slides.length) % slides.length;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }
  function next(){ goTo(current + 1); }
  function prev(){ goTo(current - 1); }

  document.getElementById('heroNext').addEventListener('click', () => { next(); restart(); });
  document.getElementById('heroPrev').addEventListener('click', () => { prev(); restart(); });

  function restart(){
    clearInterval(timer);
    if(!reduceMotion){ timer = setInterval(next, 5500); }
  }
  const heroSection = document.querySelector('.hero');
  heroSection.addEventListener('mouseenter', () => clearInterval(timer));
  heroSection.addEventListener('mouseleave', restart);
  restart();

  /* ---- Mobile nav toggle ---- */
  const toggle = document.querySelector('.nav-toggle');
  const links = document.querySelector('.nav-links');
  toggle.addEventListener('click', () => {
    const open = links.style.display === 'flex';
    links.style.display = open ? 'none' : 'flex';
    links.style.flexDirection = 'column';
    links.style.position = 'absolute';
    links.style.top = '58px';
    links.style.right = '20px';
    links.style.background = '#fff';
    links.style.padding = '16px 22px';
    links.style.borderRadius = '14px';
    links.style.boxShadow = '0 12px 30px -12px rgba(58,42,60,0.35)';
  });

  /* ---- Drama grid preview (demo data) ---- */
  const demoData = [
    {title:'《月光少年》', year:2024, country:'泰国', rating:4.8, cp:'阿哲 & 小宇', tags:['#校园','#甜蜜'], grad:'#e79cc0,#a35a89'},
    {title:'《暗巷情书》', year:2023, country:'韩国', rating:4.5, cp:'珉宇 & 道现', tags:['#职场','#年下'], grad:'#8fb9d8,#4f6f96'},
    {title:'《雨落长亭》', year:2022, country:'内地', rating:4.9, cp:'师父 & 徒弟', tags:['#古装','#虐心'], grad:'#b79ce0,#6f4f9c'},
    {title:'《深巷少年》', year:2024, country:'泰国', rating:4.3, cp:'阿海 & 小北', tags:['#校园','#青春'], grad:'#f0b3c4,#c9749a'},
    {title:'《晚风与信》', year:2021, country:'日本', rating:4.2, cp:'悠人 & 遥', tags:['#治愈','#职场'], grad:'#a9d3e6,#5f8bab'},
    {title:'《碎钻剧场》', year:2023, country:'韩国', rating:4.6, cp:'胜宇 & 泰俊', tags:['#悬疑','#虐心'], grad:'#cdb6ea,#8064b0'},
  ];

  const grid = document.getElementById('dramaGrid');
  demoData.forEach(d => {
    const card = document.createElement('div');
    card.className = 'drama-card';
    card.innerHTML = `
      <div class="card-poster" style="background:linear-gradient(160deg,${d.grad} 75%);">
        <span class="rating">★ ${d.rating}</span>
        <span class="cp-tag">${d.cp}</span>
      </div>
      <div class="card-body">
        <h3>${d.title}</h3>
        <div class="meta">${d.country} · ${d.year}</div>
        <div class="tag-list">${d.tags.map(t => `<span>${t}</span>`).join('')}</div>
      </div>
    `;
    grid.appendChild(card);
  });
})();
</script>

</body>
</html>
