    --bg:#fff8fb;
    --bg-alt:#fcf0f5;
    --pink:#f3c9db;
    --blue:#c6e3f1;
    --lavender:#ddcff2;
    --ink:#3a2a3c;
    --ink-soft:#7a6579;
    --accent:#a3406b;
    --accent-deep:#7c2f52;
    --gold:#d9a441;
    --card-radius:18px;
    --shadow-soft:0 10px 30px -14px rgba(122,63,92,0.35);
  }

  *{box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    margin:0;
    background:var(--bg);
    color:var(--ink);
    font-family:'Noto Sans SC', sans-serif;
    -webkit-font-smoothing:antialiased;
  }
  h1,h2,h3,.display{
    font-family:'Noto Serif SC', serif;
    margin:0;
  }
  a{color:inherit;text-decoration:none;}
  img{max-width:100%;display:block;}
  button{font-family:inherit;cursor:pointer;}

  /* ---------- NAV ---------- */
  .site-nav{
    position:sticky;top:0;z-index:50;
    display:flex;align-items:center;justify-content:space-between;
    padding:14px clamp(20px,5vw,56px);
    background:rgba(255,248,251,0.82);
    backdrop-filter:blur(10px);
    border-bottom:1px solid rgba(163,64,107,0.12);
  }
  .logo{
    font-family:'ZCOOL KuaiLe', cursive;
    font-size:1.9rem;font-weight:400;letter-spacing:.03em;
    color:var(--accent-deep);
    display:flex;align-items:center;gap:8px;
  }
  .logo .mark{
    width:26px;height:26px;border-radius:50%;
    background:conic-gradient(from 200deg,var(--pink),var(--blue),var(--lavender),var(--pink));
    flex-shrink:0;
  }
  .nav-links{
    display:flex;gap:28px;list-style:none;margin:0;padding:0;
    font-size:.92rem;font-weight:500;color:var(--ink-soft);
  }
  .nav-links a{
    position:relative;padding:4px 0;transition:color .2s ease;
  }
  .nav-links a::after{
    content:"";position:absolute;left:0;bottom:-2px;width:0;height:2px;
    background:linear-gradient(90deg,var(--accent),var(--lavender));
    transition:width .25s ease;
  }
  .nav-links a:hover{color:var(--accent-deep);}
  .nav-links a:hover::after{width:100%;}
  .nav-right{display:flex;align-items:center;gap:10px;}
  .nav-search{
    display:flex;align-items:center;gap:8px;
    background:var(--bg-alt);border:1px solid rgba(163,64,107,0.18);
    border-radius:999px;padding:8px 14px;font-size:.85rem;color:var(--ink-soft);
  }
  .nav-search input{
    border:none;background:transparent;outline:none;width:140px;
    font-family:inherit;font-size:.85rem;color:var(--ink);
  }
  .add-btn{
    width:34px;height:34px;border-radius:50%;border:none;flex-shrink:0;
    background:linear-gradient(135deg,var(--pink),var(--lavender));
    color:var(--accent-deep);font-size:1.15rem;font-weight:700;
    display:flex;align-items:center;justify-content:center;line-height:1;
    box-shadow:0 6px 16px -8px rgba(163,64,107,0.5);
    transition:transform .2s ease, box-shadow .2s ease;
  }
  .add-btn:hover{transform:translateY(-2px) rotate(90deg);box-shadow:0 10px 20px -8px rgba(163,64,107,0.6);}
  .nav-toggle{
    display:none;flex-direction:column;gap:4px;background:none;border:none;padding:6px;
  }
  .nav-toggle span{width:22px;height:2px;background:var(--accent-deep);border-radius:2px;}

  /* ---------- TOAST ---------- */
  .toast{
    position:fixed;left:50%;bottom:32px;transform:translate(-50%,20px);
    background:var(--accent-deep);color:#fff9fb;
    padding:12px 22px;border-radius:999px;font-size:.85rem;
    box-shadow:0 14px 30px -12px rgba(58,42,60,0.5);
    opacity:0;pointer-events:none;transition:all .3s ease;z-index:100;
  }
  .toast.show{opacity:1;transform:translate(-50%,0);}

  /* ---------- HERO ---------- */
  .hero{
    position:relative;
    margin:20px clamp(16px,4vw,48px) 0;
    border-radius:28px;
    overflow:hidden;
    background:
      radial-gradient(120% 140% at 10% 0%, var(--pink) 0%, transparent 55%),
      radial-gradient(120% 140% at 90% 10%, var(--blue) 0%, transparent 55%),
      radial-gradient(140% 160% at 50% 100%, var(--lavender) 0%, transparent 60%),
      linear-gradient(135deg,#fbeaf2,#eef4fb);
    min-height:420px;
  }
  .hero-track{position:relative;height:460px;}
  .slide{
    position:absolute;inset:0;
    display:grid;grid-template-columns:1.1fr .9fr;align-items:end;
    padding:clamp(20px,4vw,52px);
    opacity:0;visibility:hidden;
    transition:opacity .9s ease;
  }
  .slide.active{opacity:1;visibility:visible;}
  .slide-copy{position:relative;z-index:2;padding-bottom:10px;}
  .slide-eyebrow{
    display:inline-flex;align-items:center;gap:8px;
    font-size:.78rem;letter-spacing:.14em;color:var(--accent-deep);
    background:rgba(255,255,255,0.55);
    border:1px solid rgba(163,64,107,0.25);
    padding:5px 12px;border-radius:999px;margin-bottom:14px;
  }
  .slide-title{
    font-size:clamp(1.6rem,3.6vw,2.6rem);
    color:var(--ink);
    line-height:1.15;
    margin-bottom:10px;
    font-weight:900;
  }
  .slide-meta{
    display:flex;flex-wrap:wrap;gap:10px;
    font-size:.85rem;color:var(--ink-soft);margin-bottom:14px;
  }
  .slide-meta span{
    background:rgba(255,255,255,0.6);
    border:1px solid rgba(163,64,107,0.15);
    padding:3px 10px;border-radius:999px;
  }
  .slide-desc{
    max-width:48ch;color:var(--ink-soft);font-size:.92rem;line-height:1.7;margin-bottom:18px;
  }
  .slide-cta{
    display:inline-flex;align-items:center;gap:8px;
    background:var(--accent-deep);color:#fff9fb;
    padding:11px 22px;border-radius:999px;font-size:.9rem;font-weight:600;
    box-shadow:var(--shadow-soft);border:none;
    transition:transform .2s ease, box-shadow .2s ease;
  }
  .slide-cta:hover{transform:translateY(-2px);box-shadow:0 14px 32px -12px rgba(122,47,82,0.5);}

  .slide-poster{
    position:relative;z-index:2;
    justify-self:end;
    width:min(230px,80%);
    aspect-ratio:3/4.2;
    border-radius:20px;
    box-shadow:0 20px 45px -16px rgba(58,42,60,0.45);
    overflow:hidden;
  }
  .slide-poster .poster-fallback{
    position:absolute;inset:0;
    display:flex;align-items:flex-end;padding:16px;color:#fff;
  }
  .slide-poster img{
    position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
  }
  .slide.active .slide-poster img,
  .slide.active .poster-fallback{animation:kenburns 7s ease-in-out forwards;}
  @keyframes kenburns{
    0%{transform:scale(1);}
    100%{transform:scale(1.06);}
  }
  .poster-cp{
    position:relative;z-index:1;
    font-size:.78rem;font-weight:700;letter-spacing:.02em;
    background:rgba(0,0,0,0.32);backdrop-filter:blur(3px);
    padding:5px 11px;border-radius:999px;
    display:inline-flex;align-items:center;gap:4px;color:#fff;
  }

  .hero-controls{
    position:absolute;left:0;right:0;bottom:18px;
    display:flex;justify-content:center;gap:10px;z-index:3;
  }
  .hero-dot{
    width:9px;height:9px;border-radius:50%;
    background:rgba(58,42,60,0.28);border:none;padding:0;
    transition:all .25s ease;
  }
  .hero-dot.active{
    width:26px;border-radius:6px;
    background:var(--accent-deep);
  }
  .hero-arrow{
    position:absolute;top:50%;transform:translateY(-50%);
    z-index:3;width:38px;height:38px;border-radius:50%;
    background:rgba(255,255,255,0.7);border:1px solid rgba(163,64,107,0.2);
    display:flex;align-items:center;justify-content:center;
    font-size:1.1rem;color:var(--accent-deep);
    transition:background .2s ease, transform .2s ease;
  }
  .hero-arrow:hover{background:#fff;transform:translateY(-50%) scale(1.06);}
  .hero-arrow.prev{left:16px;}
  .hero-arrow.next{right:16px;}

  /* ---------- QUICK ENTRY ---------- */
  .quick-entry{
    padding:36px clamp(16px,4vw,48px) 6px;
  }
  .quick-entry h2.section-label{
    font-size:.8rem;letter-spacing:.16em;color:var(--ink-soft);
    text-transform:uppercase;margin-bottom:14px;font-family:'Noto Sans SC',sans-serif;font-weight:700;
  }
  .chip-row{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:18px;}
  .chip{
    padding:8px 18px;border-radius:999px;font-size:.86rem;font-weight:500;
    border:1px solid rgba(163,64,107,0.22);
    background:#fff;color:var(--ink-soft);
    transition:all .2s ease;
  }
  .chip:hover{
    background:linear-gradient(120deg,var(--pink),var(--lavender));
    color:var(--accent-deep);border-color:transparent;
    transform:translateY(-1px);
  }

  /* ---------- GRID PREVIEW ---------- */
  .grid-section{padding:24px clamp(16px,4vw,48px) 8px;}
  .grid-header{
    display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px;
  }
  .grid-header h2{font-size:1.5rem;color:var(--ink);}
  .grid-header a{font-size:.85rem;color:var(--accent);font-weight:600;}
  .grid-sub{font-size:.82rem;color:var(--ink-soft);margin-bottom:18px;}
  .drama-grid{
    display:grid;
    grid-template-columns:repeat(auto-fill,minmax(190px,1fr));
    gap:20px;
  }
  .drama-card{
    background:#fff;border-radius:var(--card-radius);
    overflow:hidden;border:1px solid rgba(163,64,107,0.1);
    box-shadow:0 8px 22px -16px rgba(58,42,60,0.3);
    transition:transform .25s ease, box-shadow .25s ease;
  }
  .drama-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-soft);}
  .card-poster{
    aspect-ratio:3/4;position:relative;overflow:hidden;
  }
  .card-poster .poster-fallback{
    position:absolute;inset:0;
    display:flex;align-items:flex-end;padding:12px;color:#fff;
  }
  .card-poster img{
    position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
  }
  .card-poster .cp-tag{
    position:relative;z-index:1;
    font-size:.72rem;background:rgba(0,0,0,0.34);color:#fff;
    padding:3px 9px;border-radius:999px;font-weight:600;
  }
  .card-poster .country-badge{
    position:absolute;top:10px;right:10px;z-index:1;
    font-size:.7rem;font-weight:700;color:var(--accent-deep);
    background:rgba(255,255,255,0.85);
    padding:3px 9px;border-radius:999px;
  }
  .card-body{padding:12px 14px 16px;}
  .card-body h3{font-size:.95rem;color:var(--ink);margin-bottom:4px;line-height:1.4;}
  .card-body .meta{font-size:.76rem;color:var(--ink-soft);margin-bottom:8px;}
  .card-body .summary{
    font-size:.78rem;color:var(--ink-soft);line-height:1.6;
    display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
  }

  /* ---------- FOOTER ---------- */
  footer{
    margin-top:56px;padding:38px clamp(16px,4vw,48px) 30px;
    border-top:1px solid rgba(163,64,107,0.12);
    display:flex;flex-wrap:wrap;gap:24px;justify-content:space-between;
    color:var(--ink-soft);font-size:.85rem;
  }
  footer .foot-brand{max-width:340px;}
  footer .foot-brand .display{font-family:'ZCOOL KuaiLe', cursive;font-weight:400;font-size:1.3rem;color:var(--accent-deep);margin-bottom:8px;}
  footer .foot-links{display:flex;gap:36px;flex-wrap:wrap;}
  footer .foot-links div h4{
    font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;
    color:var(--ink);margin-bottom:10px;font-family:'Noto Sans SC',sans-serif;
  }
  footer .foot-links ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;}
  footer .copyright{
    width:100%;margin-top:20px;padding-top:16px;
    border-top:1px dashed rgba(163,64,107,0.18);
    font-size:.76rem;color:var(--ink-soft);opacity:.8;
  }

  @media (max-width:760px){
    .nav-links{display:none;}
    .nav-search input{width:90px;}
    .nav-toggle{display:flex;}
    .slide{grid-template-columns:1fr;}
    .slide-poster{display:none;}
    .hero-track{height:400px;}
  }

  @media (prefers-reduced-motion: reduce){
    .slide,.slide-poster img,.poster-fallback,.hero-arrow,.chip,.drama-card,.add-btn{transition:none;animation:none;}
  }
</style>
</head>
<body>

