<script>
(function(){
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- Data: from drama_list.json (4 test entries) ---- */
  const gradients = ['#e79cc0,#a35a89','#8fb9d8,#4f6f96','#b79ce0,#6f4f9c','#f0b3c4,#c9749a'];

  function toRaw(url){
    // convert a github "blob" URL to a raw.githubusercontent.com URL so the image actually loads
    const m = url.match(/^https:\/\/github\.com\/([^/]+)\/([^/]+)\/blob\/([^/]+)\/(.+)$/);
    if(!m) return url;
    return `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}/${m[4]}`;
  }

  const dramaData = [
    {
      title: "爱在记忆被冻结时", year: 2023, country: "日本",
      image: "https://github.com/789xkxy/bl_drama_list_web/blob/7e8ba44dfc36f48ad56f47cff1746bed43f18c1f/info/pics/%E7%88%B1%E5%9C%A8%E8%AE%B0%E5%BF%86%E8%A2%AB%E5%86%BB%E7%BB%93%E6%97%B6.webp",
      summary: "性格开朗的插画家奥泽律分手后遭遇事故，唯独丢失了与池上郁哉恋爱的全部记忆。郁哉以室友身份陪伴在律身边，努力想要重启二人的恋情。",
      actors: ["本田响矢", "铃木康介"], cp: "奥泽律 × 池上郁哉",
      directors: ["安川有果", "高桥名月"], tags: []
    },
    {
      title: "等待黎明破晓时", year: 2026, country: "泰国",
      image: "https://github.com/789xkxy/bl_drama_list_web/blob/7e8ba44dfc36f48ad56f47cff1746bed43f18c1f/info/pics/The_Edge_of_Horizon.jpg",
      summary: "小王子 Tinnakorn 与奶妈的儿子 Phob 自幼相伴长大，二人之间萌生初恋，却受家族与阶级禁忌束缚。多年后 Phob 以军官身份归来，二人继续对抗世俗偏见。",
      actors: ["Inn", "Ongsa"], cp: "Phob × Tinnakorn",
      directors: ["卡塔德布・泰瓦尼"], tags: []
    },
    {
      title: "检察官的提案", year: 2026, country: "韩国",
      image: "https://github.com/789xkxy/bl_drama_list_web/blob/7e8ba44dfc36f48ad56f47cff1746bed43f18c1f/info/pics/%EA%B2%80%EC%82%AC%EC%8B%A4%EC%9D%98_%EC%A0%9C%EC%95%88poster.png",
      summary: "改编自同名小说，十五年前的命案让朱泰善与李采河背负不同命运。多年后他们在检察厅重逢，搭档追查陈年悬案，在父辈恩怨与禁忌爱恋之间挣扎。",
      actors: ["金允植", "朴时宇"], cp: "朱泰善 × 李采河",
      directors: ["杨庆熙"], tags: []
    },
    {
      title: "相逢骤雨中", year: 2025, country: "日本",
      image: "https://github.com/789xkxy/bl_drama_list_web/blob/7e8ba44dfc36f48ad56f47cff1746bed43f18c1f/info/pics/%E7%9B%B8%E9%80%A2%E9%AA%A4%E9%9B%A8%E4%B8%AD.webp",
      summary: "电器销售萩原一显误发邮件，与总务部半井整匿名结识。二人靠邮件倾诉秘密，情感逐步越界。",
      actors: ["武藤润", "伊藤明日阳"], cp: "萩原一显 × 半井整",
      directors: ["高桥名月", "富田未来"], tags: []
    }
  ].map((d, i) => Object.assign(d, { raw: toRaw(d.image), grad: gradients[i % gradients.length] }));

  /* ---- Build hero slides ---- */
  const heroTrack = document.getElementById('heroTrack');
  dramaData.forEach((d, i) => {
    const slide = document.createElement('div');
    slide.className = 'slide' + (i === 0 ? ' active' : '');
    slide.style.background = `linear-gradient(120deg, rgba(243,201,219,0.4), rgba(198,227,241,0.3))`;
    slide.innerHTML = `
      <div class="slide-copy">
        <div class="slide-eyebrow">✦ 测试数据</div>
        <h1 class="slide-title">《${d.title}》</h1>
        <div class="slide-meta"><span>${d.country}</span><span>${d.year}</span></div>
        <p class="slide-desc">${d.summary}</p>
        <a class="slide-cta" href="#">进入剧集详情 →</a>
      </div>
      <div class="slide-poster">
        <div class="poster-fallback" style="background:linear-gradient(160deg, ${d.grad} 75%);">
          <span class="poster-cp">${d.cp}</span>
        </div>
        <img src="${d.raw}" alt="${d.title}" loading="lazy"
             onerror="this.remove();">
      </div>
    `;
    heroTrack.appendChild(slide);
  });

  /* ---- Hero carousel logic ---- */
  const slides = document.querySelectorAll('.slide');
  const dotsWrap = document.getElementById('heroDots');
  let current = 0, timer;

  slides.forEach((_, i) => {
    const dot = document.createElement('button');
    dot.className = 'hero-dot' + (i === 0 ? ' active' : '');
    dot.setAttribute('aria-label', '第 ' + (i + 1) + ' 张');
    dot.addEventListener('click', () => goTo(i));
    dotsWrap.appendChild(dot);
  });
  const dots = document.querySelectorAll('.hero-dot');

  function goTo(index){
    slides[current].classList.remove('active');
    dots[current].classList.remove('active');
    current = (index + slides.length) % slides.length;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }
  function next(){ goTo(current + 1); }
  function prev(){ goTo(current - 1); }

  document.getElementById('heroNext').addEventListener('click', () => { next(); restart(); });
  document.getElementById('heroPrev').addEventListener('click', () => { prev(); restart(); });

  function restart(){
    clearInterval(timer);
    if(!reduceMotion && slides.length > 1){ timer = setInterval(next, 5500); }
  }
  const heroSection = document.querySelector('.hero');
  heroSection.addEventListener('mouseenter', () => clearInterval(timer));
  heroSection.addEventListener('mouseleave', restart);
  restart();

  /* ---- Mobile nav toggle ---- */
  const toggle = document.querySelector('.nav-toggle');
  const links = document.querySelector('.nav-links');
  toggle.addEventListener('click', () => {
    const open = links.style.display === 'flex';
    links.style.display = open ? 'none' : 'flex';
    links.style.flexDirection = 'column';
    links.style.position = 'absolute';
    links.style.top = '58px';
    links.style.right = '20px';
    links.style.background = '#fff';
    links.style.padding = '16px 22px';
    links.style.borderRadius = '14px';
    links.style.boxShadow = '0 12px 30px -12px rgba(58,42,60,0.35)';
  });

  /* ---- + Add drama button (placeholder for future feature) ---- */
  const toast = document.getElementById('toast');
  let toastTimer;
  document.getElementById('addDramaBtn').addEventListener('click', () => {
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2400);
  });

  /* ---- Drama grid preview (from dramaData) ---- */
  const grid = document.getElementById('dramaGrid');
  dramaData.forEach(d => {
    const card = document.createElement('div');
    card.className = 'drama-card';
    card.innerHTML = `
      <div class="card-poster">
