  footer .foot-links{display:flex;gap:36px;flex-wrap:wrap;}
  footer .foot-links div h4{
    font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;
    color:var(--ink);margin-bottom:10px;font-family:'Noto Sans SC',sans-serif;
  }
  footer .foot-links ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;}
  footer .copyright{
    width:100%;margin-top:20px;padding-top:16px;
    border-top:1px dashed rgba(163,64,107,0.18);
    font-size:.76rem;color:var(--ink-soft);opacity:.8;
  }

  @media (max-width:760px){
    .nav-links{display:none;}
    .nav-search input{width:90px;}
    .nav-toggle{display:flex;}
    .slide{grid-template-columns:1fr;}
    .slide-poster{display:none;}
    .hero-track{height:400px;}
  }

  @media (prefers-reduced-motion: reduce){
    .slide,.slide-poster img,.poster-fallback,.hero-arrow,.chip,.drama-card,.add-btn{transition:none;animation:none;}
  }
</style>
</head>
