    heroTrack.appendChild(slide);
    applyPosterTint(slide.querySelector('img'), slide, slide.querySelector('.poster-fallback'), d.variant);
  });

  /* ---- Hero carousel logic ---- */
  const slides = document.querySelectorAll('.slide');
  const dotsWrap = document.getElementById('heroDots');
  let current = 0, timer;

  slides.forEach((_, i) => {
    const dot = document.createElement('button');
    dot.className = 'hero-dot' + (i === 0 ? ' active' : '');
    dot.setAttribute('aria-label', '第 ' + (i + 1) + ' 张');
    dot.addEventListener('click', () => goTo(i));
    dotsWrap.appendChild(dot);
  });
  const dots = document.querySelectorAll('.hero-dot');

  function goTo(index){
    slides[current].classList.remove('active');
    dots[current].classList.remove('active');
    current = (index + slides.length) % slides.length;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }
  function next(){ goTo(current + 1); }
  function prev(){ goTo(current - 1); }

  document.getElementById('heroNext').addEventListener('click', () => { next(); restart(); });
  document.getElementById('heroPrev').addEventListener('click', () => { prev(); restart(); });

  function restart(){
    clearInterval(timer);
    if(!reduceMotion && slides.length > 1){ timer = setInterval(next, 5500); }
  }
  const heroSection = document.querySelector('.hero');
  heroSection.addEventListener('mouseenter', () => clearInterval(timer));
  heroSection.addEventListener('mouseleave', restart);
  restart();

  /* ---- Mobile nav toggle ---- */
  const toggle = document.querySelector('.nav-toggle');
  const links = document.querySelector('.nav-links');
  toggle.addEventListener('click', () => {
    const open = links.style.display === 'flex';
    links.style.display = open ? 'none' : 'flex';
    links.style.flexDirection = 'column';
    links.style.position = 'absolute';
    links.style.top = '58px';
    links.style.right = '20px';
